import re


def parse_duration(text: str) -> int:
    """Convert a duration string like '1h30m', '45s', '2h' into total seconds.

    Raises ValueError for empty, negative, or malformed input.
    """
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    text = text.strip()
    if not text:
        raise ValueError("Empty duration string")

    # Match sequences of <number><unit> where unit is h, m, or s
    pattern = re.compile(r'^(\d+[hms])+$')
    if not pattern.match(text):
        raise ValueError(f"Malformed duration string: {text!r}")

    total_seconds = 0
    # Extract all number-unit pairs
    matches = re.findall(r'(\d+)([hms])', text)

    for num_str, unit in matches:
        value = int(num_str)
        if value < 0:
            raise ValueError("Negative duration component")

        if unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value

    return total_seconds
