fn reverse_words(sentence: &str) -> String {
    sentence
        .split_whitespace()
        .rev()
        .collect::<Vec<&str>>()
        .join(" ")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reverses_simple_sentence() {
        assert_eq!(reverse_words("hello world"), "world hello");
    }

    #[test]
    fn handles_multiple_spaces() {
        assert_eq!(reverse_words("a  b   c"), "c b a");
    }

    #[test]
    fn single_word() {
        assert_eq!(reverse_words("hello"), "hello");
    }

    #[test]
    fn empty_string() {
        assert_eq!(reverse_words(""), "");
    }
}
```

This function splits the input on whitespace, reverses the word order, and joins them back with single spaces. It normalizes multiple consecutive spaces into one, which is a reasonable default for "words in a sentence." If you need to preserve original spacing exactly, that requires a different approach (e.g., tracking token positions).
